import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Command-Line Search (lff)","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/cli.md","filePath":"user-guide/cli.md","lastUpdated":1785993908000}'),n={name:"user-guide/cli.md"};function r(o,e,l,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="command-line-search-lff" tabindex="-1">Command-Line Search (lff) <a class="header-anchor" href="#command-line-search-lff" aria-label="Permalink to &quot;Command-Line Search (lff)&quot;">​</a></h1><p>Lertaro also ships a small command-line companion, <strong><code>lff</code></strong> — an fzf-style fuzzy finder that searches through the same index the App itself already maintains, instead of duplicating any of that setup. It&#39;s for anyone who lives in a terminal and wants Lertaro&#39;s search (fuzzy matching, pinyin aliasing, network drives, everything) available there too, not just in the search windows.</p><p><code>lff</code> needs the Lertaro App to already be running — it talks to the App over a local, per-user pipe rather than re-scanning anything itself. If the App isn&#39;t running, <code>lff</code> fails fast with an error on stderr instead of hanging.</p><h2 id="setting-it-up" tabindex="-1">Setting it up <a class="header-anchor" href="#setting-it-up" aria-label="Permalink to &quot;Setting it up&quot;">​</a></h2><p><code>lff.exe</code> is installed alongside the App. Check <strong>Add the lff command-line search tool to PATH</strong> on the installer&#39;s task selection page to make it runnable as <code>lff</code> from any terminal — this adds Lertaro&#39;s install folder to your system PATH. Open a new terminal window afterward; one already open when you installed won&#39;t pick up the change.</p><p>If you skipped that option, you can still run it directly from wherever Lertaro is installed.</p><h2 id="basic-usage" tabindex="-1">Basic usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic usage&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lff</span></span></code></pre></div><p>opens an interactive picker: type to fuzzy-filter, exactly like the App&#39;s own search — including pinyin-alias matching for Chinese filenames (see <a href="./search-syntax.html">Search Syntax</a>).</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td>Type</td><td>Filter results</td></tr><tr><td>↑ / ↓</td><td>Move the highlight</td></tr><tr><td>Page Up / Page Down</td><td>Jump a page at a time</td></tr><tr><td>← / →</td><td>Move the text cursor within the query</td></tr><tr><td>Tab</td><td>Toggle-select the highlighted result (marked rows show <code>*</code>)</td></tr><tr><td>Enter</td><td>Print the selected path(s) — or just the highlighted one, if nothing&#39;s marked — and exit</td></tr><tr><td>Esc / Ctrl+C</td><td>Exit without printing anything</td></tr></tbody></table><h2 id="pre-filling-the-query" tabindex="-1">Pre-filling the query <a class="header-anchor" href="#pre-filling-the-query" aria-label="Permalink to &quot;Pre-filling the query&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lff report</span></span></code></pre></div><p>and</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo report | lff</span></span></code></pre></div><p>both open already filtered to <code>report</code>. Either way this only pre-fills the query box and starts the same search typing it would — it never auto-selects or auto-prints a result on its own, so you still navigate and press Enter/Tab yourself.</p><h2 id="selecting-multiple-results" tabindex="-1">Selecting multiple results <a class="header-anchor" href="#selecting-multiple-results" aria-label="Permalink to &quot;Selecting multiple results&quot;">​</a></h2><p>Tab marks or unmarks the highlighted row. Marked rows persist even after you change the query — so you can search for one file, mark it, search for something else, mark that too, and so on. The status line shows how many are currently marked. Pressing Enter while anything is marked prints every marked path, one per line, regardless of what&#39;s currently highlighted.</p><h2 id="using-the-result-in-another-command" tabindex="-1">Using the result in another command <a class="header-anchor" href="#using-the-result-in-another-command" aria-label="Permalink to &quot;Using the result in another command&quot;">​</a></h2><p><code>lff</code>&#39;s interactive picker is drawn directly to the console, never through the normal input/output streams — the only thing that ever goes to stdout is the final selected path(s), one per line, printed on Enter. That&#39;s what lets its output compose with the usual shell techniques for capturing another command&#39;s result.</p><p>PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code (lff)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lff; code $path</span></span></code></pre></div><p>cmd.exe (no built-in command substitution — use <code>for /f</code>):</p><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;delims=&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> %</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i in (</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&#39;lff&#39;) do code &quot;%i&quot;</span></span></code></pre></div><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>No preview pane — deliberately out of scope, since the App&#39;s own <a href="./actions-and-preview.html">Actions Menu &amp; Preview</a> already covers that.</li><li>Requires the Lertaro App to be running; <code>lff</code> doesn&#39;t index anything on its own.</li></ul>`,25)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
